import React from "react";

function Header() {
    return (
        <div className="header">
            <div className="brand-logo">
                <img src="/logo192.png" alt="IITM Logo" />
            </div>
            <div className="user-info">
                <h1>Exhibitor Dashboard</h1>
                <p>IITM India</p>
            </div>
        </div>
    );
}

export default Header;
